/bin/bash -lc "python3 -m py_compile /workspace/openai_client.py && python3 - <<'PY'
import json
import openai_client
sample = {\"output\": [{\"type\": \"message\", \"content\": [{\"type\": \"output_text\", \"text\": \"hello\"}]}]}
assert openai_client.output_text(sample) == \"hello\"
try:
    openai_client.ask(\"private\", model=\"test\", api_key=\"\")
except ValueError as exc:
    assert \"OPENAI_API_KEY\" in str(exc)
else:
    raise AssertionError(\"missing-key check failed\")
print(\"validation passed\")
PY"

